public DMFExecutionId exportToPackageV2(DMFPackageName packageName, SharedServiceUnitURL packageUrl, DMFDefinitionGroupName definitionGroupId, DMFExecutionId executionId, boolean reExecute, DataAreaName legalEntityId, boolean createPackage, Map entitySyncVersion, int previewCount, str _messageId)
{

    ISMTelemetryDMF telemetry = new ISMTelemetryDMF();
    telemetry.addRuntimeProperty('packageName', packageName);
    telemetry.addRuntimeProperty('packageUrl', packageUrl);
    telemetry.addRuntimeProperty('definitionGroupId', definitionGroupId);
    telemetry.addRuntimeProperty('executionId', executionId);
    telemetry.addRuntimeProperty('reExecute',  any2Str(reExecute));
    telemetry.addRuntimeProperty('legalEntityId', legalEntityId);
    telemetry.addRuntimeProperty('createPackage', any2Str(createPackage));
    //telemetry.addRuntimeProperty('entitySyncVersion', entitySyncVersion);
    //telemetry.addRuntimeProperty('previewCount', previewCount);
    telemetry.addRuntimeProperty('_messageId', _messageId);


    DMFExecutionId ret = next exportToPackageV2(packageName, packageUrl, definitionGroupId, executionId, reExecute, legalEntityId, createPackage, entitySyncVersion, previewCount, _messageId);

    telemetry.processEvent(ISMTelemetryEventNames::DMFExportPackage);

    return ret;
}

public static SharedServiceUnitFileID exportToFileV2(DMFDefinitionGroupName _definitionGroup, DMFExecutionId _executionId, DMFEntityName _entity, DMFSourceName _sourceFormat, Map _entitySyncVersion, int _previewCount)
{

    ISMTelemetryDMF telemetry = new ISMTelemetryDMF();
    telemetry.addRuntimeProperty('_definitionGroup', _definitionGroup);
    telemetry.addRuntimeProperty('_executionId', _executionId);
    telemetry.addRuntimeProperty('_entity', _entity);
    telemetry.addRuntimeProperty('_sourceFormat', _sourceFormat);
    //telemetry.addRuntimeProperty('_entitySyncVersion', _entitySyncVersion);
    telemetry.addRuntimeProperty('_previewCount', int2Str(_previewCount));

    SharedServiceUnitFileID sourceFilepath = next exportToFileV2(_definitionGroup, _executionId, _entity, _sourceFormat, _entitySyncVersion, _previewCount);

    telemetry.processEvent(ISMTelemetryEventNames::DMFExportFile);

    return sourceFilepath;
}
